package com.aegisdispatch.model;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="dispatches") public class Dispatch { @Id private UUID id; @Column(name="emergency_id") private UUID emergencyId; @Column(name="ambulance_id") private UUID ambulanceId; @Column(name="dispatcher_name") private String dispatcherName; private String status; @Column(name="distance_km") private double distanceKm; @Column(name="eta_minutes") private double etaMinutes; private double score; @Column(name="hospital_id") private UUID hospitalId; @Column(name="assigned_at") private Instant assignedAt; @Column(name="accepted_at") private Instant acceptedAt; @Column(name="completed_at") private Instant completedAt;
 public UUID getId(){return id;} public void setId(UUID v){id=v;} public UUID getEmergencyId(){return emergencyId;} public void setEmergencyId(UUID v){emergencyId=v;} public UUID getAmbulanceId(){return ambulanceId;} public void setAmbulanceId(UUID v){ambulanceId=v;} public String getDispatcherName(){return dispatcherName;} public void setDispatcherName(String v){dispatcherName=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public double getDistanceKm(){return distanceKm;} public void setDistanceKm(double v){distanceKm=v;} public double getEtaMinutes(){return etaMinutes;} public void setEtaMinutes(double v){etaMinutes=v;} public double getScore(){return score;} public void setScore(double v){score=v;} public UUID getHospitalId(){return hospitalId;} public void setHospitalId(UUID v){hospitalId=v;} public Instant getAssignedAt(){return assignedAt;} public void setAssignedAt(Instant v){assignedAt=v;} public Instant getAcceptedAt(){return acceptedAt;} public void setAcceptedAt(Instant v){acceptedAt=v;} public Instant getCompletedAt(){return completedAt;} public void setCompletedAt(Instant v){completedAt=v;}
}
